#!/usr/bin/env python3
"""Build the offline visual index from the delivered files."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parents[1]
LABELS = {
    'cloudberry-landscape': 'Морошка, горы и озеро', 'mountain-dawn': 'Горный рассвет',
    'lake-sunset': 'Озеро на закате', 'starry-night': 'Звёздное небо', 'cloudberry-macro': 'Крупный план морошки',
    'brain-glow': 'Светящийся мозг', 'knowledge-book': 'Раскрытая книга', 'neural-network': 'Нейронная сеть',
    'balance-stones': 'Равновесие', 'idea-tree': 'Дерево на закате',
    'cloudberry-3d': 'Объёмная морошка', 'cloudberry-sprig': 'Веточка морошки', 'app-icon-3d': 'Иконка приложения',
}

def main():
    items = []
    for p in sorted((ROOT / 'assets/raster/backgrounds').glob('*.webp')):
        topic, orientation = p.stem.rsplit('-', 1)
        items.append(dict(path=str(p.relative_to(ROOT)), title=LABELS[topic], kind='backgrounds',
                          detail='9:16 · 900×1600' if orientation == 'portrait' else '16:9 · 1600×900',
                          master='assets/masters/backgrounds/' + p.with_suffix('.png').name))
    for p in sorted((ROOT / 'assets/raster/illustrations').glob('*.webp')):
        items.append(dict(path=str(p.relative_to(ROOT)), title=LABELS[p.stem], kind='illustrations', detail='1280×720 · WebP',
                          master='assets/masters/illustrations/' + p.with_suffix('.png').name))
    for name in ('cloudberry-3d', 'cloudberry-sprig', 'app-icon-3d'):
        items.append(dict(path=f'assets/raster/brand/{name}.png', title=LABELS[name], kind='brand',
                          detail='PNG · прозрачность' if name != 'app-icon-3d' else 'PNG · квадрат',
                          master=f'assets/masters/brand/{name}.png'))
    for p in sorted((ROOT / 'assets/brand').glob('*mono*.svg')) + sorted((ROOT / 'assets/brand').glob('wordmark*.svg')):
        items.append(dict(path=str(p.relative_to(ROOT)), title=p.stem, kind='brand', detail='Редактируемый SVG', master=None))
    for p in sorted((ROOT / 'assets/icons').glob('*.svg')):
        items.append(dict(path=str(p.relative_to(ROOT)), title=p.stem, kind='icons', detail='24×24 · currentColor',
                          master='assets/icons-png/' + p.with_suffix('.png').name))
    for name, title in [('01.png','Первоначальная концепция'),('02.png','Гибридная концепция'),('03.png','Полировка экранов'),
                        ('04-asset-board.png','Исходный планшет'),('05-approved-reference.png','Референс пользователя')]:
        items.append(dict(path='mockups/' + name, title=title, kind='mockups', detail='Оригинал без изменений', master=None))
    cards = []
    for item in items:
        href, title, kind, detail = [escape(item[k], quote=True) for k in ('path','title','kind','detail')]
        second = '' if not item['master'] else f'<a href="{escape(item["master"], quote=True)}" download>{"PNG" if kind == "icons" else "Мастер PNG"}</a>'
        cards.append(f'''<article class="card" data-kind="{kind}" data-search="{title.lower()} {href.lower()}">
          <a class="picture {kind}" href="{href}" target="_blank" rel="noopener" aria-label="Открыть: {title}"><img src="{href}" alt="{title}" loading="lazy"></a>
          <div class="card-body"><h3>{title}</h3><p>{detail}</p><div class="links"><a href="{href}" download>Скачать</a>{second}</div><code>{href}</code></div></article>''')
    (ROOT / 'assets/catalog.json').write_text(json.dumps({'version':'2.2','items':items}, ensure_ascii=False, indent=2) + '\n')
    template = '''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light dark"><title>Морошка — графический комплект 2.2</title>
<style>
@font-face{font-family:Manrope;src:url('assets/fonts/Manrope-Variable.ttf') format('truetype');font-weight:200 800;font-display:swap}
:root{--bg:#fcf5f2;--surface:#fff;--ink:#48374e;--muted:#69536d;--line:#e4d5df;--accent:#794298;--shadow:0 10px 32px #48374e0c;--wash:#f8e8f1}
:root[data-theme=dark]{--bg:#211b29;--surface:#302638;--ink:#fff4f5;--muted:#d3bed3;--line:#65536d;--accent:#d8b8f5;--shadow:0 10px 32px #0002;--wash:#46334e}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 Manrope,system-ui,sans-serif}a{color:var(--accent);text-underline-offset:4px}button,input{font:inherit}button,a,input{touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:4px}button{cursor:pointer}header,main,footer{max-width:1280px;margin:auto;padding:0 24px}header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:24px;padding-bottom:20px}.brand{font-size:24px;font-weight:800;text-decoration:none;color:var(--ink);display:flex;align-items:center;gap:10px}.brand img{width:46px;height:46px;object-fit:contain}.quiet{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:14px;padding:10px 16px;min-height:48px}h1,h2,h3,p{margin:0}h1{font-size:clamp(30px,4vw,48px);line-height:1.15;letter-spacing:-1.5px;max-width:740px}h2{font-size:24px;line-height:1.3}h3{font-size:16px;line-height:1.4;overflow-wrap:anywhere}.hero{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:center;margin:20px 0 32px}.hero p{color:var(--muted);max-width:700px;margin-top:20px}.hero-art{height:300px;background:#302638;border-radius:28px;overflow:hidden;box-shadow:var(--shadow)}.hero-art img{width:100%;height:100%;object-fit:cover}.eyebrow{display:block;color:var(--accent);font-size:13px;font-weight:800;letter-spacing:1.5px;margin-bottom:16px}.stats{display:flex;gap:28px;margin-top:24px;flex-wrap:wrap}.stats b{font-size:25px;display:block;line-height:1.25}.stats span{font-size:13px;color:var(--muted)}.resources{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:32px}.resources a{min-height:48px;border:1px solid var(--line);border-radius:14px;padding:10px 16px;background:var(--surface);text-decoration:none;font-weight:700}.resources .primary{background:linear-gradient(115deg,#b84f3b,#794298);color:#fff;border-color:transparent}.notice{padding:20px 24px;border:1px solid var(--line);border-radius:20px;background:var(--surface);font-size:14px;color:var(--muted);margin-bottom:32px}.notice strong{color:var(--ink)}.toolbox{display:flex;gap:16px;flex-wrap:wrap;justify-content:space-between;align-items:center;margin-bottom:18px}.filters{display:flex;gap:6px;flex-wrap:wrap}.filters button{min-height:48px;border:1px solid transparent;border-radius:999px;background:transparent;color:var(--muted);padding:9px 15px}.filters button[aria-pressed=true]{background:var(--wash);color:var(--ink);border-color:var(--line);font-weight:800}.search{min-height:48px;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);padding:10px 14px;width:260px;max-width:100%}.result-line{font-size:13px;color:var(--muted);margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.card{overflow:hidden;background:var(--surface);border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow)}.picture{height:210px;display:flex;align-items:center;justify-content:center;overflow:hidden;background:var(--wash);padding:0}.picture img{width:100%;height:100%;object-fit:contain}.picture.brand{background:repeating-conic-gradient(#fff 0% 25%,#f4ebf0 0% 50%) 50%/24px 24px;padding:16px}.picture.brand img{width:100%;height:100%;object-fit:contain}.picture.icons{height:140px;background:#fff}.picture.icons img{width:48px;height:48px}.picture.mockups{background:#eee1e8;padding:8px;height:260px}.card-body{padding:16px}.card-body p{font-size:13px;color:var(--muted);margin-top:6px}.links{display:flex;gap:16px;margin:10px 0 6px}.links a{font-size:14px;min-height:44px;display:flex;align-items:center;font-weight:700}code{font:11px/1.5 ui-monospace,monospace;display:block;color:var(--muted);overflow-wrap:anywhere}.empty{padding:48px 16px;text-align:center;color:var(--muted)}[hidden]{display:none!important}.kit{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:48px 0 32px;padding:28px;border-radius:24px;border:1px solid var(--line);background:var(--surface)}.kit p{color:var(--muted);margin:12px 0 20px}.kit img{width:100%;max-height:340px;object-fit:contain;background:#fcf5f2;border-radius:16px}.kit a{display:inline-block;min-height:48px;padding:10px 0;font-weight:700}footer{font-size:13px;color:var(--muted);padding-top:16px;padding-bottom:40px}.footer-links{display:flex;gap:20px;flex-wrap:wrap;margin-top:12px}.footer-links a{min-height:44px;display:flex;align-items:center}@media(max-width:900px){.hero{grid-template-columns:1fr 240px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hero-art{height:260px}}@media(max-width:600px){header,main,footer{padding-left:16px;padding-right:16px}.brand{font-size:22px}.hero{grid-template-columns:1fr;margin-top:12px}.hero-art{height:220px}.grid{grid-template-columns:1fr}.picture{height:240px}.kit{grid-template-columns:1fr;padding:20px}.search{width:100%}.filters{gap:2px}.filters button{padding:8px 11px;font-size:14px}.stats{gap:22px}h1{letter-spacing:-.8px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
</style></head><body>
<header><a class="brand" href="index.html"><img src="assets/raster/brand/cloudberry-3d.png" alt="">Морошка</a><button class="quiet" id="theme" aria-pressed="false">Тёмная тема</button></header>
<main><section class="hero"><div><span class="eyebrow">ГРАФИЧЕСКИЙ КОМПЛЕКТ · 2.2</span><h1>Всё для пространства ваших мыслей</h1><p>Оригинальные макеты, отдельные иллюстрации, иконки и компоненты в одном месте. Выберите нужный ресурс, откройте оригинал или скачайте файл для приложения.</p><div class="stats"><div><b>18</b><span>художественных мастеров</span></div><div><b>37</b><span>пиктограмм</span></div><div><b>5</b><span>исходных макетов</span></div></div></div><div class="hero-art"><img src="assets/raster/backgrounds/cloudberry-landscape-landscape.webp" alt="Морошка у горного озера на закате"></div></section>
<nav class="resources" aria-label="Материалы для разработчика"><a class="primary" href="assets/components/showcase.html">Компоненты и состояния</a><a href="HANDOFF.md">Передача разработчику</a><a href="ASSET_COVERAGE.md">Сверка с планшетом</a><a href="manifest.json">Перечень файлов</a></nav>
<aside class="notice"><strong>Оригиналы сохранены без изменений.</strong> Отдельная художественная графика воссоздана по референсу. PNG-мастера и точные промпты включены в комплект. SVG-компоненты редактируются и импортируются в Figma; нативный файл .fig не заявляется.</aside>
<section aria-labelledby="gallery-heading"><h2 id="gallery-heading">Библиотека ресурсов</h2><div class="toolbox"><div class="filters" role="group" aria-label="Категории"><button data-filter="all" aria-pressed="true">Всё</button><button data-filter="backgrounds" aria-pressed="false">Фоны</button><button data-filter="illustrations" aria-pressed="false">Иллюстрации</button><button data-filter="brand" aria-pressed="false">Бренд</button><button data-filter="icons" aria-pressed="false">Иконки</button><button data-filter="mockups" aria-pressed="false">Макеты</button></div><input class="search" id="search" type="search" placeholder="Найти ресурс…" aria-label="Поиск ресурсов"></div><p class="result-line" id="result-count" role="status"></p><div class="grid" id="gallery">__CARDS__</div><p class="empty" id="empty" hidden>По этому запросу ничего не найдено.</p></section>
<section class="kit"><div><span class="eyebrow">РЕДАКТИРУЕМЫЕ КОМПОНЕНТЫ</span><h2>Единый язык интерфейса</h2><p>Кнопки, теги, поля, карточки, граф, голосовая волна, навигация и состояния. Светлая и тёмная темы, доступные названия и настройка движения.</p><a href="assets/components/ui-kit.svg" download>Скачать редактируемый SVG →</a><br><a href="assets/components/showcase.html">Открыть интерактивный пример →</a></div><a href="assets/components/ui-kit-preview.png"><img src="assets/components/ui-kit-preview.png" alt="Обзор компонентов Морошки" loading="lazy"></a></section>
</main><footer><p>В основе — согласованная концепция «Морошки». Примеры не заменяют реальные пользовательские данные и не подтверждают внедрение функций в приложение.</p><div class="footer-links"><a href="SOURCES.md">Источники и происхождение</a><a href="assets/fonts/OFL.txt">Лицензия шрифта</a><a href="SPEC.md">Спецификация</a><a href="prototype.html">Прежний прототип</a></div></footer>
<script>
(()=>{let category='all';const cards=[...document.querySelectorAll('.card')];const buttons=[...document.querySelectorAll('[data-filter]')];const search=document.querySelector('#search');function apply(){const query=search.value.trim().toLocaleLowerCase('ru');let count=0;for(const card of cards){const show=(category==='all'||card.dataset.kind===category)&&card.dataset.search.includes(query);card.hidden=!show;if(show)count++;}document.querySelector('#result-count').textContent='Показано ресурсов: '+count;document.querySelector('#empty').hidden=count>0;}for(const button of buttons){button.addEventListener('click',()=>{category=button.dataset.filter;for(const b of buttons)b.setAttribute('aria-pressed',String(b===button));apply();});}search.addEventListener('input',apply);const theme=document.querySelector('#theme');theme.addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';theme.setAttribute('aria-pressed',String(dark));theme.textContent=dark?'Светлая тема':'Тёмная тема';});apply();})();
</script></body></html>'''
    (ROOT / 'index.html').write_text(template.replace('__CARDS__', '\n'.join(cards)), encoding='utf-8')
    print(json.dumps({'cards':len(items),'file':'index.html'}, ensure_ascii=False))

if __name__ == '__main__':
    main()
